interface EmailFieldProps {
  id: string;
  label: string;
  required?: boolean;
  defaultValue?: string;
}

export const EmailField: React.FC<EmailFieldProps> = ({ 
  id, 
  label, 
  required = false, 
  defaultValue = '' 
